<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #1a1a2e;
    color: #eee;
    font-family: Arial, Helvetica, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
  }
  h1 { font-size: 2.4rem; margin-bottom: 0.4rem; color: #e0e0e0; }
  #score {
    font-size: 1.4rem;
    margin-bottom: 1rem;
    background: #16213e;
    padding: 0.4rem 1.2rem;
    border-radius: 6px;
    color: #f0c040;
    font-weight: bold;
  }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(4, 1fr);
    gap: 8px;
    width: 360px;
    height: 360px;
    background: #16213e;
    border-radius: 10px;
    padding: 8px;
  }
  .cell {
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 1.6rem;
    background: #0f3460;
    color: #ccc;
    transition: background 0.12s, color 0.12s;
  }
  .cell[data-val="2"]    { background: #e3f2fd; color: #333; }
  .cell[data-val="4"]    { background: #bbdefb; color: #333; }
  .cell[data-val="8"]    { background: #ffcc0c; color: #333; }
  .cell[data-val="16"]   { background: #ff9800; color: #fff; }
  .cell[data-val="32"]   { background: #f44336; color: #fff; }
  .cell[data-val="64"]   { background: #e91e63; color: #fff; }
  .cell[data-val="128"]  { background: #9c27b0; color: #fff; font-size: 1.4rem; }
  .cell[data-val="256"]  { background: #673ab7; color: #fff; font-size: 1.4rem; }
  .cell[data-val="512"]  { background: #3f51b5; color: #fff; font-size: 1.4rem; }
  .cell[data-val="1024"] { background: #2196f3; color: #fff; font-size: 1.1rem; }
  .cell[data-val="2048"] { background: #00bcd4; color: #fff; font-size: 1.1rem; }
  #reset {
    margin-top: 1rem;
    padding: 0.55rem 1.6rem;
    font-size: 1rem;
    border: none;
    border-radius: 6px;
    background: #e94560;
    color: #fff;
    cursor: pointer;
    font-weight: bold;
  }
  #reset:hover { background: #c73650; }
</style>
</head>
<body>

<h1>2048</h1>
<div id="score">Score: 0</div>
<div id="board"></div>
<button id="reset">New Game</button>

<script>
(function () {
  const SIZE = 4;
  let grid = [];
  let score = 0;

  /* ---- helpers ---- */
  function copyGrid(g) { return g.map(r => r.slice()); }

  function emptyGrid() {
    const g = [];
    for (let i = 0; i < SIZE; i++) g.push(new Array(SIZE).fill(0));
    return g;
  }

  function emptyCells(g) {
    const cells = [];
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (g[r][c] === 0) cells.push([r, c]);
    return cells;
  }

  function spawnTile(g) {
    const empty = emptyCells(g);
    if (empty.length === 0) return false;
    const [r, c] = empty[Math.floor(Math.random() * empty.length)];
    g[r][c] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  /* ---- slide / merge a single line ---- */
  // line is an array of 4 numbers (already zeros removed, or with zeros)
  // returns { merged: new line (length 4 with zeros padded), points }
  function slideLine(line) {
    let pts = 0;
    // filter out zeros
    const vals = line.filter(v => v !== 0);
    const out = [];
    let i = 0;
    while (i < vals.length) {
      if (i + 1 < vals.length && vals[i] === vals[i + 1]) {
        const merged = vals[i] * 2;
        out.push(merged);
        pts += merged;
        i += 2;
      } else {
        out.push(vals[i]);
        i++;
      }
    }
    // pad to SIZE
    while (out.length < SIZE) out.push(0);
    return { merged: out, points: pts };
  }

  /* ---- core move ---- */
  function doMove(dir) {
    const prev = copyGrid(grid);
    let earned = 0;

    if (dir === 'left') {
      for (let r = 0; r < SIZE; r++) {
        const result = slideLine(grid[r]);
        grid[r] = result.merged;
        earned += result.points;
      }
    } else if (dir === 'right') {
      for (let r = 0; r < SIZE; r++) {
        const reversed = grid[r].slice().reverse();
        const result = slideLine(reversed);
        grid[r] = result.merged.reverse();
        earned += result.points;
      }
    } else if (dir === 'up') {
      for (let c = 0; c < SIZE; c++) {
        const col = [];
        for (let r = 0; r < SIZE; r++) col.push(grid[r][c]);
        const result = slideLine(col);
        for (let r = 0; r < SIZE; r++) grid[r][c] = result.merged[r];
        earned += result.points;
      }
    } else if (dir === 'down') {
      for (let c = 0; c < SIZE; c++) {
        const col = [];
        for (let r = 0; r < SIZE; r++) col.push(grid[r][c]);
        const reversed = col.reverse();
        const result = slideLine(reversed);
        const final = result.merged.reverse();
        for (let r = 0; r < SIZE; r++) grid[r][c] = final[r];
        earned += result.points;
      }
    }

    // check if anything changed
    let changed = false;
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (grid[r][c] !== prev[r][c]) { changed = true; break; }
      if (changed) break;

    if (changed) {
      score += earned;
      spawnTile(grid);
    }

    render();
    return changed;
  }

  /* ---- rendering ---- */
  function render() {
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const cell = document.createElement('div');
        cell.className = 'cell';
        const val = grid[r][c];
        if (val !== 0) {
          cell.textContent = val;
          cell.setAttribute('data-val', val);
        }
        boardEl.appendChild(cell);
      }
    }
    document.getElementById('score').textContent = 'Score: ' + score;
  }

  /* ---- reset ---- */
  function reset() {
    grid = emptyGrid();
    score = 0;
    spawnTile(grid);
    spawnTile(grid);
    render();
  }

  /* ---- public API ---- */
  const game = {
    size: SIZE,
    reset: reset,
    move: function (dir) { return doMove(dir); },
    board: function () { return copyGrid(grid); },
    setBoard: function (arr) {
      grid = arr.map(r => r.slice());
      render();
    },
    score: function () { return score; }
  };
  window.game = game;

  /* ---- keyboard ---- */
  const keyMap = {
    ArrowLeft: 'left',
    ArrowRight: 'right',
    ArrowUp: 'up',
    ArrowDown: 'down'
  };
  document.addEventListener('keydown', function (e) {
    if (keyMap[e.key]) {
      e.preventDefault();
      game.move(keyMap[e.key]);
    }
  });

  /* ---- reset button ---- */
  document.getElementById('reset').addEventListener('click', reset);

  /* ---- init ---- */
  reset();
})();
</script>

</body>
</html>
